unsafe fn putd(out:*mut u8,off:usize,x:f64){let b=x.to_le_bytes();for k in 0..8{*out.add(off+k)=b[k]}}
fn token(vals:&[i64])->Option<u64>{let mut key=0u64;for &raw in vals{let mut x=raw;if (65..=90).contains(&x){x+=32}if !((97..=122).contains(&x)||(48..=57).contains(&x)||x==39){return None}key=key*128+x as u64}Some(key)}
#[no_mangle]
pub unsafe extern "C" fn naive_bayes_text_classification(v:*const i64,n:usize,out:*mut u8,cap:usize)->i64{if v.is_null()||n<7{return -1}let a=std::slice::from_raw_parts(v,n);let d=a[0];let alpha=a[1];if !(2..=6).contains(&d)||!(1..=10000).contains(&alpha){return -1}let mut words=[0u64;6];let mut labels=[0usize;6];let mut seen=[false;2];let mut total=[0usize;2];let mut pos=2usize;for i in 0..d as usize{if pos+2>n{return -1}let lab=a[pos];let len=a[pos+1];pos+=2;if !(0..=1).contains(&lab)||!(0..=8).contains(&len)||pos+len as usize>n{return -1}let word=match token(&a[pos..pos+len as usize]){Some(x)=>x,None=>return -1};words[i]=word;labels[i]=lab as usize;seen[labels[i]]=true;total[labels[i]]+=usize::from(len>0);pos+=len as usize}if pos>=n{return -1}let qlen=a[pos];pos+=1;if !(0..=8).contains(&qlen)||pos+qlen as usize!=n||!seen[0]||!seen[1]{return -1}let query=match token(&a[pos..]){Some(x)=>x,None=>return -1};let vocab=(0..d as usize).filter(|&i|words[i]!=0&&(0..i).all(|j|words[j]!=words[i])).count();if vocab==0&&qlen>0{return -1}if out.is_null()||cap<16{return -2}let mut s=[0.0f64;2];for c in 0..2{let mut docs=0;let mut count=0;for i in 0..d as usize{if labels[i]==c{docs+=1;if qlen>0&&words[i]==query{count+=1}}}s[c]=(docs as f64/d as f64).ln();if qlen>0{let sm=alpha as f64/1000.0;s[c]+=((count as f64+sm)/(total[c] as f64+sm*vocab as f64)).ln()}}let hi=s[0].max(s[1]);let x=(s[0]-hi).exp();let y=(s[1]-hi).exp();putd(out,0,x/(x+y));putd(out,8,y/(x+y));16}
